insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b513bf0-055a-46fd-973d-38cfb88f4ca0', 'es', '¿Qué formas de mirar favorecen una buena primera impresión?', '["Un contacto visual tranquilo", "Pausas naturales", "Una expresión amable", "Mirarla fijamente sin parpadear"]'::jsonb, 'Un contacto visual equilibrado y amable transmite confianza y naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b9394c8-71a4-4281-9046-5014c86b7514', 'es', 'Abres la conversación. Ella responde con calidez, pero luego su amiga la toma del brazo y se la lleva.', '["Cortés: estaba siendo amable antes de que la interrumpiera su amiga", "Abierta al principio, pero una interrupción externa lo cortó", "Fría: usó a su amiga como excusa para escaparse"]'::jsonb, 'Su respuesta cálida era abierta; la interrupción de su amiga es un factor externo, no una señal de ella.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ccbf131-6df9-4829-afc6-793d8a586ba6', 'es', 'Ella te sonríe. Empiezas a planear tu frase de apertura. ¿Cuál es la mejor jugada?', '["Ensayar lo que vas a decir y luego ir", "Ir hacia ella de inmediato, aunque no tengas una frase pulida", "Esperar a que vuelva a mirarte para confirmarlo"]'::jsonb, 'Actuar rápido impide que la duda crezca. Muévete en los tres segundos después de verla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21c693ec-ce2c-4a1c-b6a4-e5c07cc9e39f', 'es', 'Hablas tan bajo que ella tiene que adivinar parte de lo que dices. ¿Qué genera esto?', '["Una atracción fuerte e inmediata", "Una presencia perfectamente ajustada", "Un aire misterioso e intrigante", "Un roce que estropea la fluidez"]'::jsonb, 'Hablar sin claridad añade una tensión innecesaria a la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21ca0984-0243-415e-ab95-8d472e631a12', 'es', 'Te acercas a una mujer en la terraza de una cafetería. ¿Qué movimientos transmiten soltura?', '["Pasos rápidos y apresurados con los hombros encogidos", "Brazos rígidos pegados al cuerpo y andar tieso", "Ritmo constante, brazos que se mueven con naturalidad y postura erguida", "Pasos dudosos mirando al suelo"]'::jsonb, 'Moverte relajado transmite que no hay peligro y le hace más fácil la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('243e45da-4e6e-4747-bd72-4c71c92d582b', 'es', 'La ves, pero no vas bien vestido. ¿Qué deberías hacer?', '["Acercarte de todos modos", "No hacerlo; tu aspecto va a arruinar tus posibilidades", "Esperar hasta estar listo", "Mirarla a los ojos, pero sin hablarle"]'::jsonb, 'Si solo te acercas en condiciones perfectas, acabas haciendo muy pocos intentos. Puedes acercarte en cualquier momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ae814b-7816-4ac9-af4c-f56e4e9d8de9', 'es', '¿Por qué las aperturas indirectas se sienten menos como una interrupción?', '["Evitan el silencio", "Muestran seguridad", "Se suman al momento que los dos ya están viviendo"]'::jsonb, 'Un contexto compartido hace que tu entrada se sienta esperable y sea fácil responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ebc378-571a-47ca-a34d-406494e05bf1', 'es', 'Ves que está dibujando algo en su cuaderno. ¿Qué apertura muestra curiosidad?', '["“Tienes pinta de artista.”", "“¿Me puedo sentar aquí?”", "“Tienes talento, se nota.”", "“¿Qué estás dibujando? Se ve muy detallado.”"]'::jsonb, 'La curiosidad por sus experiencias invita a una conexión real, sin intenciones ocultas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26e9ec88-6ad1-419a-a087-c91efb8998d2', 'es', '¿Qué hábitos te ayudan a ser constante al acercarte a largo plazo?', '["Hablar con gente todos los días", "Esperar a sentirte listo", "Conversar en lugares del día a día"]'::jsonb, 'Participar con regularidad baja la presión y hace que las interacciones se sientan más fáciles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2726ad43-344c-4ec6-a996-4df4d37978f4', 'es', 'Ves a una mujer con un accesorio muy original. ¿Qué podrías decir primero para despertar curiosidad?', '["“¿Dónde lo conseguiste?”", "“Tengo una pregunta rápida sobre eso que llevas puesto.”", "“Qué bonito, me gusta.”", "“¿Eres de por aquí?”"]'::jsonb, 'El planteamiento crea curiosidad antes de revelar la pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29a122e7-d801-4e7c-bf05-40a46aba0960', 'es', 'Ella está sola haciendo fila. Quieres pedirle su opinión. ¿Cuál es la mejor apertura?', '["“Hola, ¿qué tal tu día?”", "“Pregunta rápida: ¿eres más de café o de té?”", "“¿Qué crees que está mejor, la bebida de temporada o la de siempre?”"]'::jsonb, 'Plantear un dilema invita a dar su opinión, y eso la hace sentirse valorada e incluida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ada2eb4-7e4e-4ea9-b9d1-7cde29ea6304', 'es', 'Apenas se gira y te dice un “hola” sin ganas. ¿Qué indica esto?', '["Timidez", "Curiosidad", "Interés neutro", "Una respuesta fría"]'::jsonb, 'Una participación mínima significa que te retires; despídete bien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b69af0f-cead-4bcb-8f8d-580b110d13f2', 'es', '¿Qué señal indica con más claridad una actitud fría?', '["Sonreír brevemente", "Responder a tus preguntas", "Darte la espalda", "Reírse por cortesía"]'::jsonb, 'Un cuerpo orientado hacia otro lado indica desinterés. Retírate.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d63f1fb-98b5-4678-aec8-6b0c2abded25', 'es', 'Se gira hacia ti, sonríe con calidez, responde con detalle, pero sigue mirando hacia sus amigas.', '["Abierta: hacer preguntas muestra interés aunque esté pendiente de sus amigas", "Cortés: es amable, pero las miradas repetidas muestran una atención dividida", "Neutra: solo está pendiente de sus amigas; sigue con normalidad"]'::jsonb, 'Sus respuestas indican una participación cortés, pero su atención no está del todo contigo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2f7b8ecd-021a-40d3-aea3-50d2530f7f6e', 'es', 'Te responde con calidez, pero sigue deslizando la pantalla de su celular. ¿Qué deberías suponer?', '["Que es tímida", "Que está abierta", "Que está distraída pero interesada", "Que está siendo cortés"]'::jsonb, 'Una atención dividida suele indicar cortesía, no interés real.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fa1ad2f-3496-4f7e-b850-7253ba88fd6b', 'es', 'Se ríe con tu apertura y te mira de frente, pero cruza los brazos. ¿Qué está pasando?', '["Abierta: la risa y mirarte de frente muestran interés, a pesar de los brazos", "Cortés: una risa forzada con lenguaje corporal cerrado significa desinterés", "Mixta: la risa y mirarte de frente son abiertos, pero los brazos cruzados son duda"]'::jsonb, 'La risa indica comodidad y los brazos cruzados, reserva; sigue con un tono ligero.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3583c492-59dd-4eb4-a7c9-c98966901e7d', 'es', 'Ves que lleva una taza de café muy original. ¿Qué podrías decir primero para despertar curiosidad?', '["“Te tengo que preguntar algo sobre esa taza.”", "“¿Dónde conseguiste esa taza?”", "“Qué divertida tu taza.”", "“¿Vienes aquí a menudo?”"]'::jsonb, 'El planteamiento crea curiosidad antes de revelar la pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36134173-386a-4742-a375-45b16eeb371f', 'es', '¿Qué exige marcar bien el tono?', '["Esperar a que ella te dé permiso o señales para seguir", "Elegir tú el tema en lugar de sumarte a su mundo", "Hacer avanzar la interacción sin esperar a que ella la lleve"]'::jsonb, 'Marcar el tono significa llevar el tema y el avance de la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('365d84da-247e-427e-a603-8e7d2900f73f', 'es', 'Te responde con amabilidad, pero dice: “Creo que ya me tengo que ir pronto”. ¿Qué es esto?', '["Cortés con un límite suave: participa, pero indica que tiene poco tiempo", "Abierta: la respuesta amable muestra interés; lo de irse es solo cortesía", "Mixta: su participación choca con lo que dice de irse"]'::jsonb, 'Está siendo considerada mientras marca un límite; reconócelo y despídete con educación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3669c3ab-5f36-42cb-932f-6277589d1d8e', 'es', '¿Por qué es importante leer su primera reacción?', '["La obliga a estar abierta", "Mantiene la interacción cómoda para los dos", "Respeta su espacio y sus señales", "Evita cruzar límites que ella no ha abierto"]'::jsonb, 'Leer bien las señales mantiene la comodidad y el aplomo de los dos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3717fc9d-129b-426e-a329-a0e904cfd1e1', 'es', 'Te da una respuesta corta, aparta la mirada y cambia el peso de un pie a otro. ¿Qué deberías hacer?', '["Ser breve y despedirte con elegancia", "Insistir con más preguntas para engancharla", "Avanzar para generar atracción", "Hacerle un cumplido para que entre en confianza"]'::jsonb, 'Las señales neutras o corteses significan que bajes el ritmo o te retires, para respetar su comodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3763474f-7119-463b-a740-ab5dd1bb8606', 'es', 'Te acercas a ella mientras lee un libro en una cafetería. ¿Qué apertura mantiene una actitud firme?', '["“Perdón por molestarte, pero quería saludarte.”", "“¿Está ocupado este asiento?”", "“Ese libro se ve interesante. ¿De qué trata?”", "“Disculpa, ¿puedo hablar contigo un minuto?”"]'::jsonb, 'Ir directo y dar por hecho que habrá conversación marca el tono sin disculparte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('381417bd-9910-49a2-b9c7-271afc73bcf9', 'es', '¿Qué resultados trae no hacer nada?', '["Un fracaso asegurado", "Protección contra el rechazo", "Ninguna conexión ni posibilidad", "Un arrepentimiento que dura"]'::jsonb, 'No hacer nada garantiza oportunidades perdidas y un arrepentimiento duradero.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38ade8d0-fc3e-4396-9791-5b19775afa46', 'es', 'Te acercas a ella en un espacio abierto. ¿Qué deberías evitar?', '["Detenerte a una distancia social con una postura abierta", "Bloquearle una posible salida", "Acercarte en un ángulo de 45 grados, a la vista", "Dejar un metro de espacio"]'::jsonb, 'Bloquear las salidas incomoda, incluso en espacios abiertos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3a61650f-61dd-4d87-b302-9c1fad8a6217', 'es', '¿Por qué el toque juguetón es importante al plantear la conversación?', '["Quita presión y hace que la interacción se sienta divertida en vez de seria", "Un planteamiento juguetón genera atracción a través de una experiencia emocional positiva", "Muestra que estás cómodo", "Todas las anteriores"]'::jsonb, 'Todo es cierto: el toque juguetón quita presión, genera emociones positivas y muestra que estás cómodo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3aa54f55-0812-4c14-be64-8fed1f814fb4', 'es', '¿Qué señal distingue mejor la receptividad de la cortesía?', '["Sonreír", "El contacto visual", "Hacerte preguntas a ti también", "Asentir"]'::jsonb, 'La reciprocidad es un indicador de interés más claro que las demás.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b44889c-1e0c-4a51-8846-e7d4ea05c95b', 'es', 'Te acercas a ella mientras hace fila. Te dice: “La verdad es que tengo prisa”. ¿Cuál es la mejor respuesta?', '["“Tranquila, solo quería saludarte”, y te vas con naturalidad", "Pedirle perdón por molestarla y dar un paso atrás", "Ignorar lo que dijo y seguir hablando"]'::jsonb, 'No fuerces la conversación ni te disculpes; mantenlo ligero y sigue tu camino.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c06a35a-c102-4ca8-bce5-02e0afa2b5a6', 'es', 'Discoteca. Se fueron con ella a una zona más tranquila. ¿Qué sigue?', '["Seguir conversando y proponer verse otro día", "Pedirle su contacto ahora, mientras el ritmo es bueno", "Proponer ir juntos a otro lugar", "Pedirle su número o proponer ir juntos a otro sitio, según la logística y sus señales"]'::jsonb, 'Con un buen ritmo toca dar el siguiente paso: asegurar el contacto o proponer seguir en otro lado si sus señales dicen que sí.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c98c86a-c4c9-43a5-be53-6cad77bf34c5', 'es', '¿Cuándo deberías terminar una interacción?', '["Cuando da señales frías: participación mínima, cuerpo cerrado, girada hacia otro lado", "Cuando las señales de cortesía persisten: respuestas cortas, poca reciprocidad", "Cuando el tiempo o las circunstancias hacen que no tenga sentido seguir", "Todas las anteriores"]'::jsonb, 'Una despedida limpia protege su comodidad y tu actitud cuando no hay interés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3caf0039-8d00-42c1-8c5a-9b57ae2ac717', 'es', 'Te dice: “La verdad es que estoy en medio de algo”, pero sigue sonriendo y mirándote de frente.', '["Abierta: la sonrisa pesa más que las palabras", "Cortés: marca un límite con respeto", "Mixta: insiste un poco", "Fría: cualquier límite es un rechazo"]'::jsonb, 'Un límite claro con calidez es una forma cortés de retirarse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3dfb88ca-871e-4a7e-b233-6335a1bd949a', 'es', 'Estás conversando y notas que su amiga está rondando cerca. ¿Cuál es la mejor jugada?', '["Ignorar a la amiga y seguir", "Competir por la atención", "Incluir brevemente a la amiga y luego volver a evaluar", "Avanzar de inmediato"]'::jsonb, 'Incluirla reduce la tensión social y te mantiene al mando.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3ebc28c1-d1f2-41ee-a393-af6d74a978a9', 'es', 'Se ríe, pero sigue girándose hacia otro lado. ¿Qué pesa más?', '["Su risa", "Tu apertura", "Su lenguaje corporal", "El lugar"]'::jsonb, 'Cuando las señales se contradicen, confía en las físicas; si se gira, dale espacio o retírate.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40d53e0a-03ba-435a-8d62-e1fcb096eded', 'es', '¿Qué hace que una apertura indirecta se sienta natural y fácil de recibir?', '["Decir algo ingenioso o impresionante", "Un entorno o un momento que los dos están viviendo", "El momento perfecto"]'::jsonb, 'Un contexto compartido hace que tu entrada se sienta esperable y sea fácil responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4232f870-74a7-4557-9e29-70a586b48204', 'es', 'La ves en un bar. ¿Cuál es el acercamiento directo?', '["Comentar algo de la música o las bebidas para iniciar la conversación", "Mirarla a los ojos y sonreír", "“Me llamaste la atención y quería venir a presentarme”"]'::jsonb, 'Las aperturas directas dicen abiertamente y desde el principio que hay un interés romántico.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('478e1b59-9821-4b03-8744-b950a6269270', 'es', 'Ves a una mujer con un reloj antiguo. ¿Qué apertura genera participación?', '["“Hola, ¿cómo va tu noche?”", "“Te ves bien.”", "“¿A qué te dedicas?”", "“Ese reloj parece tener toda una historia detrás.”"]'::jsonb, 'Las suposiciones concretas la obligan a participar y responder de forma personal.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48e4513c-c89e-4a8b-99e3-d70a28ea7193', 'es', 'Haciendo fila. Le dices: “Estás demasiado tranquila para esta fila”. Ella se ríe. ¿Qué está funcionando?', '["Hiciste referencia a la situación que comparten", "Creaste un contraste juguetón", "Le pediste permiso para hablar"]'::jsonb, 'Un contexto compartido con un toque juguetón baja la resistencia rápido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4de13376-2210-4667-8d5f-ae59a38657c2', 'es', '¿Por qué es mejor aclarar su interés con un paso directo que quedarte dando vueltas?', '["Acorta la interacción", "Muestra liderazgo", "Evita el rechazo", "Le da claridad y el control a ella"]'::jsonb, 'Una frase clara elimina la ambigüedad: revela si su amabilidad es interés o simple cortesía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ef57d59-ef61-4420-92a6-2b920652d1b8', 'es', '¿Por qué las aperturas de opinión hacen que la gente se sienta valorada?', '["Al pedir su perspectiva, le dices explícitamente que su criterio importa", "Pedir opiniones demuestra inteligencia emocional y habilidades sociales", "A la gente le gusta más hablar de sí misma que escuchar"]'::jsonb, 'La gente se ilumina cuando su punto de vista importa. Sentirse valorada genera participación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4fe08740-af66-4896-aa93-6a50f2a41020', 'es', 'Te dice: “La verdad es que ya me iba”, pero se queda y sigue haciéndote preguntas.', '["Retirada cortés", "Señal mixta que tiende a abierta", "Señal fría suavizada por cortesía", "Rechazo rotundo"]'::jsonb, 'Que se quede y siga con curiosidad indica apertura, aunque tenga que irse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5027deaf-2157-42e1-b4db-138c9801e876', 'es', 'Sonríe, responde con buena actitud, pero dice: “La verdad es que estoy estudiando para un examen”.', '["Abierta: la buena respuesta muestra interés, aunque mencione el estudio", "Rechazo cortés: es amable, pero el estudio marca un límite", "Prueba: quiere ver si insistes o si respetas sus prioridades"]'::jsonb, 'Un tono amable puede ser cortesía; una prioridad dicha en voz alta es un límite. Deséale suerte y despídete.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50916cec-9c9c-486c-b266-a45065ff3ea2', 'es', 'Responde con entusiasmo y te hace una pregunta, pero sigue revisando el celular.', '["Abierta: lo que dice muestra interés real, a pesar del celular", "Cortés: revisar el celular contradice la calidez de sus palabras y muestra una atención dividida", "Mixta: lo que dice es abierto, pero su comportamiento sugiere distracción"]'::jsonb, 'Las señales mixtas exigen leer la situación; sigue un poco más para ver si su atención vuelve.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51786178-0f86-4cb1-b4bd-0b3e68a87f9e', 'es', '¿Por qué es arriesgado confundir cortesía con interés?', '["Hace más lenta la interacción", "La somete a una presión que no quiere", "Hace que el acercamiento parezca atrevido"]'::jsonb, 'Su comodidad va primero; usa las señales para decidir cuándo seguir y cuándo aflojar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51944bdf-42d0-42e5-b902-ff0f21714718', 'es', 'Participa con calidez, se ríe, te hace preguntas, pero te dice: “La verdad es que tengo novio”.', '["Abierta: su participación muestra interés; lo del novio es una prueba", "Cortés: su calidez era simpatía, y lo del novio es un límite claro", "Mixta: muestra interés, pero su situación sentimental genera un conflicto"]'::jsonb, 'Estaba siendo amable, no mostrando interés romántico; mencionar a su novio es un límite claro.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51f130a3-2032-4c6f-b654-83d546e7b8aa', 'es', 'Fiesta. Ella es amable, pero no lo tienes claro. ¿Qué frases ayudan?', '["“Voy a pedir algo de tomar. ¿Vienes?”", "“Esta fiesta está un poco aburrida.”", "“Te dejo para que saludes a más gente.”", "“Ven, te presento a mis amigos.”"]'::jsonb, 'Las propuestas decididas comprueban, sin presión, si quiere moverse, sumarse o seguir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
